svg.script:

(function() {
  var root = document.querySelector('.a12p1-root');
  if (!root) return;

  function setActive(id) {
    root.setAttribute('data-active', id);
  }

  // Add click and keyboard handlers for territory shapes and label boxes
  var clickables = root.querySelectorAll('.a12p1-territory, .a12p1-tab-btn');
  clickables.forEach(function(el) {
    var id = el.getAttribute('data-id');
    if (!id) return;

    var handler = function(e) {
      e.preventDefault();
      e.stopPropagation();
      var current = root.getAttribute('data-active');
      // If clicking the currently active specific tab/shape, return to 'all', else activate id
      if (current === id && id !== 'all') {
        setActive('all');
      } else {
        setActive(id);
      }
    };

    el.addEventListener('click', handler);
    el.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        handler(e);
      }
    });
  });
})();
